// Builds the VENORA wordmark as SVG outlines from Marcellus.
// The wordmark must be real paths so it can serve as a CSS mask-image (data-URI SVGs cannot load webfonts).
// Output: src/content/wordmark.ts (generated, do not edit by hand).
//
//   pnpm wordmark
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import opentype, { type Path } from "opentype.js";

const root = fileURLToPath(new URL("..", import.meta.url));
const fontBuf = readFileSync(`${root}node_modules/@fontsource/marcellus/files/marcellus-latin-400-normal.woff`);
const font = opentype.parse(fontBuf.buffer.slice(fontBuf.byteOffset, fontBuf.byteOffset + fontBuf.byteLength) as ArrayBuffer);

const SIZE = 200;
const TRACKING = 0.06 * SIZE; // the logo is set with open spacing
const text = "VENORA";

let x = 0;
const glyphPaths: { ch: string; path: Path }[] = [];
for (const ch of text) {
  const glyph = font.charToGlyph(ch);
  glyphPaths.push({ ch, path: glyph.getPath(x, SIZE, SIZE) });
  x += (glyph.advanceWidth ?? 0) * (SIZE / font.unitsPerEm) + TRACKING;
}
x -= TRACKING;

// opentype.js 2.0 returns these WOFF outlines with the y axis inverted; mirror them about the
// wordmark's vertical centre so the letters stand upright.
const ys = glyphPaths.flatMap(({ path }) => path.commands.flatMap((c) => (c.y === undefined ? [] : [c.y])));
const flipAxis = Math.min(...ys) + Math.max(...ys);
for (const { path } of glyphPaths) {
  for (const c of path.commands) {
    if (c.y !== undefined) c.y = flipAxis - c.y;
    if (c.y1 !== undefined) c.y1 = flipAxis - c.y1;
    if (c.y2 !== undefined) c.y2 = flipAxis - c.y2;
  }
}

const parts = glyphPaths.map(({ path }) => path.toPathData({ decimalPlaces: 2 }));
const oPath = glyphPaths.find((g) => g.ch === "O")?.path;
if (!oPath) throw new Error("No O glyph");
const oBox = oPath.getBoundingBox();
const boxes = glyphPaths.map(({ path }) => path.getBoundingBox());
const all = {
  x1: Math.min(...boxes.map((b) => b.x1)),
  y1: Math.min(...boxes.map((b) => b.y1)),
  y2: Math.max(...boxes.map((b) => b.y2)),
};

// Signature detail from the Venora logo: a small dot centred inside the O.
const cx = (oBox.x1 + oBox.x2) / 2;
const cy = (oBox.y1 + oBox.y2) / 2;
const r = SIZE * 0.035;
const dot = `M${(cx - r).toFixed(2)} ${cy.toFixed(2)}a${r} ${r} 0 1 0 ${(2 * r).toFixed(2)} 0a${r} ${r} 0 1 0 ${(-2 * r).toFixed(2)} 0Z`;

const pad = 2;
const minX = Math.floor(all.x1) - pad;
const minY = Math.floor(all.y1) - pad;
const height = Math.ceil(all.y2 - all.y1) + pad * 2;
const width = Math.ceil(x - all.x1) + pad * 2;
const viewBox = `${minX} ${minY} ${width} ${height}`;
const d = [...parts, dot].join("");

const out = `// Generated by scripts/build-wordmark.ts from Marcellus (OFL). Do not edit by hand.
// A typeset stand-in for the Venora logo until vector artwork is supplied (docs/design-system.md).
export const wordmark = {
  viewBox: "${viewBox}",
  width: ${width},
  height: ${height},
  d: "${d}",
} as const;
`;
writeFileSync(`${root}src/content/wordmark.ts`, out);
console.log(`wordmark: ${width}×${height}, ${d.length} chars`);
